/* shape.h: the client sees only the product interface */
struct shape;                       /* opaque: no fields visible */
struct shape *shape_create(enum shape_kind kind, double a);
void shape_draw(const struct shape *s);
void shape_destroy(struct shape *s);

/* shape.c: the one place that knows the concrete types */
struct shape *shape_create(enum shape_kind kind, double a) {
    switch (kind) {
    case SHAPE_CIRCLE: return circle_create(a);
    case SHAPE_SQUARE: return square_create(a);
    default:           return NULL;   /* defined failure mode */
    }
}
